-- Study Abroad country content, BATCH 21: India, Albania, Bosnia, North Macedonia, Montenegro, Belarus, Liechtenstein, Andorra.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('india', 'albania', 'bosnia-and-herzegovina', 'north-macedonia', 'montenegro', 'belarus', 'liechtenstein', 'andorra'));
UPDATE countries SET why_title = 'Why study in India?', why_body = '<p>India has one of the world''s largest higher education systems, with top institutes such as the IITs and IISc and low costs, plus a Study in India (SII) portal for international students.<ul><li>Large choice of English-medium degrees</li><li>Strong in engineering, technology, medicine and management</li><li>Low tuition and living costs</li><li>Special e-student visa for students registered on the SII portal</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Since January 2025 India offers an <strong>e-student visa</strong> for foreign students registered on the Study in India (SII) portal, and an <strong>e-student-x visa</strong> for dependants. Both can be valid for up to five years, with extensions possible.</p><ul><li>Admission from an institution listed on the SII portal</li><li>Apply on indianvisaonline.gov.in using your Study in India ID</li><li>Visa is for full-time undergraduate, postgraduate and PhD programmes at accredited institutions</li><li>These rules date from January 2025, so check current changes</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Indian Ministry of Home Affairs and the Study in India portal site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply to each institution directly or through the Study in India portal.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Entrance exams such as JEE for IITs, or institute tests</li><li>Statement of purpose and references for postgraduate courses</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees depend on the institution; no IIT fee figures were found in the search.</p><ul><li>IIT and other institute fees: check each institute for international student rates</li><li>About 75% of international students study at undergraduate level, 15% postgraduate and 4% PhD (UGC official)</li><li>Living costs: about US$250-$600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS or TOEFL where required; most programmes are in English</li></ul>' WHERE slug = 'india';
UPDATE countries SET why_title = 'Why study in Albania?', why_body = '<p>Albania offers low-cost, English- and Albanian-taught degrees, especially medicine and dentistry, in a Mediterranean setting.<ul><li>Low tuition and living costs</li><li>Medicine and dentistry programmes</li><li>Mediterranean climate and location</li><li>Growing number of international students</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Students staying over 90 days need a <strong>residence permit for study</strong>, applied for through e-Albania within 30 days of entering, so you must already be in Albania.</p><ul><li>Admission letter from an Albanian institution</li><li>Apply within 30 days of entry through e-Albania; the university international office helps</li><li>Fees depend on the type and duration of the permit</li><li>Passport, photographs, health insurance and proof of funds</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official e-Albania and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university, which publishes criteria, quotas and fees each year (University of Tirana quotas for 2026-27 were approved on 19 March 2026).</p><ul><li>Academic transcripts and certificates, apostilled and homologated</li><li>Language proof (Albanian or English)</li><li>Entrance exam for medicine</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition depends on the university and programme.</p><ul><li>Medicine in Albanian at the University of Medicine, Tirana: about €3,000-€7,000 a year (secondary source, March 2026)</li><li>University of Tirana 2026-27 fees: check its admissions page</li><li>Living costs: about €400-€700 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects; medicine needs biology and chemistry</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English or Albanian proof depending on programme</li></ul>' WHERE slug = 'albania';
UPDATE countries SET why_title = 'Why study in Bosnia and Herzegovina?', why_body = '<p>Bosnia and Herzegovina offers low-cost degrees at the University of Sarajevo and private institutions such as the International University of Sarajevo, with some English-taught programmes.<ul><li>Low tuition and living costs</li><li>English-taught programmes at private universities</li><li>Rich Balkan history and culture</li><li>Central European location</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Students staying over 90 days need a <strong>White Card</strong> and a <strong>temporary residence permit</strong> from the Foreign Affairs Office. Entry visa needs depend on nationality.</p><ul><li>Register for the White Card within 48 hours of arrival (University of Sarajevo guidance)</li><li>Residence permit in the first month of arrival; one university quotes about €300 for the process</li><li>Visa-required students apply for a D visa after the invitation letter is verified</li><li>Passport valid at least three months beyond the residence period</li><li>Apostilled certificate and vaccination record may be required</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official the Bosnian Ministry of Foreign Affairs and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>English proof (IUS cites TOEFL iBT 80)</li><li>Entrance exam for medicine and some faculties</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees differ between public and private universities.</p><ul><li>University of Sarajevo (public): estimated €500-€1,500 or BAM 1,000-3,000 a year for international students (third-party)</li><li>International University of Sarajevo: PhD fee listed at €9,000 (older page €8,500)</li><li>Living costs: about €400-€650 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English or local language proof depending on programme</li></ul>' WHERE slug = 'bosnia-and-herzegovina';
UPDATE countries SET why_title = 'Why study in North Macedonia?', why_body = '<p>North Macedonia offers affordable degrees at Ss. Cyril and Methodius University in Skopje and other universities, with growing English-taught programmes, especially in IT and medicine.<ul><li>Low tuition and living costs</li><li>English-taught programmes in IT and other fields</li><li>Central Balkan location</li><li>EU candidate country</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Students first apply for a <strong>long-stay (D) visa</strong> at an embassy, then for a <strong>temporary residence permit</strong> at the Ministry of Internal Affairs in Skopje.</p><ul><li>Admission letter and D visa from the North Macedonian embassy</li><li>Residence permit application to the Ministry of Internal Affairs; UKIM lists a fee of about €40 (visa fee reported at €60 elsewhere, unconfirmed)</li><li>Health insurance for the stay; the permit covers study only</li><li>Job work needs a separate work permit</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official North Macedonian Ministry of Internal Affairs and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>UKIM publishes yearly competition documents for first, second and third cycle; foreign students apply through its foreign student application.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>English or Macedonian language proof</li><li>Entrance exam for some faculties</li><li>Motivation letter for Master''s programmes</li><li>Passport copy and photographs; 2025 first-cycle window ran to 29 September (confirm)</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>UKIM tables list separate domestic and foreign fees.</p><ul><li>2026/27 second cycle example: Mathematics Master''s €1,500 domestic and €2,250 foreign</li><li>2025/26 first cycle example: Geography €2,100 domestic and €3,150 foreign</li><li>A ranking site gives a flat €2,000, which conflicts; use the UKIM tables</li><li>Living costs: about €350-€600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English or Macedonian proof depending on programme</li></ul>' WHERE slug = 'north-macedonia';
UPDATE countries SET why_title = 'Why study in Montenegro?', why_body = '<p>Montenegro offers low-cost study on the Adriatic, with the University of Montenegro and private universities offering some English-taught programmes in tourism, hospitality and environmental science.<ul><li>Low tuition and living costs</li><li>Adriatic coast and mountain setting</li><li>Tourism and hospitality focus</li><li>EU candidate country</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Students staying over 90 days apply in Montenegro for a <strong>temporary residence permit</strong> at the Ministry of Interior after arrival. Sources conflict on some details.</p><ul><li>Admission letter from a Montenegrin institution</li><li>Proof of financial means and accommodation</li><li>Health insurance from an authorised insurer or under an agreement</li><li>Work: one guide says study permit holders may work, with limits of 15-20 hours; sources conflict</li><li>Post-study stay: sources conflict (nine-month job-search permit vs no route)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Montenegrin Ministry of Interior and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university.</p><ul><li>Academic transcripts and certificates, apostilled</li><li>English or local language proof</li><li>Entrance exam for some faculties</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees are the least consistent area in sources.</p><ul><li>One guide says public bachelor''s and master''s programmes are tuition-free unless taught in a foreign language</li><li>Other guides give €750 a year for undergraduates or €2,000-€3,500 for public universities</li><li>English-taught programmes usually charge fees; check the University of Montenegro fee decision</li><li>Living costs: about €450-€800 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English or Montenegrin proof depending on programme</li></ul>' WHERE slug = 'montenegro';
UPDATE countries SET why_title = 'Why study in Belarus?', why_body = '<p>Belarus offers low-cost degrees in medicine, engineering and IT at state universities, with Russian-taught and some English-taught programmes. Check current travel and sanctions advice.<ul><li>Low tuition and living costs</li><li>Medicine, dentistry and engineering</li><li>Preparatory year for foreign students</li><li>Established university system</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Universities issue an <strong>invitation to study</strong> that applicants use to get a study visa from a Belarusian consulate (if a visa is required). Guides describe a long-term student visa valid for 90 days, then a temporary residence permit.</p><ul><li>Invitation letter from the university international office</li><li>Passport, photographs, medical certificate and HIV test</li><li>Visa fee reported at €60 by a commercial site; check the consulate</li><li>Register and apply for a temporary residence permit after arrival</li><li>Check government travel and visa advice for your country</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Belarusian consulate and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university, usually with a preparatory department year for language.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof (Russian or English)</li><li>Interview or exam in chemistry and biology for medicine</li><li>Passport copy and photographs</li><li>Medical certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees are quoted in various currencies by different universities.</p><ul><li>BSU bachelor''s: reported BYN 11,000-17,100 a year (third-party)</li><li>Grodno State Medical University: General Medicine in Russian, RUB 350,000 for 2026/27; English-medium was US$5,000 in 2025/26</li><li>BSMU: dentistry €4,700 and pharmacy €4,200 a year (agency)</li><li>Living costs: about US$200-$400 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Russian or English proof depending on programme</li></ul>' WHERE slug = 'belarus';
UPDATE countries SET why_title = 'Why study in Liechtenstein?', why_body = '<p>Liechtenstein is a small Alpine country with one main university, the University of Liechtenstein, focused on business, finance, architecture and information systems.<ul><li>Small, personal university with strong business and finance programmes</li><li>English-taught Master''s programmes</li><li>High quality of life</li><li>Central European location near Switzerland and Austria</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Most non-EU students need a <strong>visa</strong> to enter, then a <strong>short-term study permit (L)</strong> from the Migration and Passport Office.</p><ul><li>Admission letter from the University of Liechtenstein</li><li>Visa processing can take several weeks (6-8 weeks estimated)</li><li>A CHF 3,000 deposit for processing, refunded at the end of studies</li><li>Work: students may work up to 35% in semester and 100% in breaks, with advance permit approval</li><li>Post-study job-seeking permit: sources conflict, so check with the Migration and Passport Office</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Migration and Passport Office and the University of Liechtenstein site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to the University of Liechtenstein through its application portal.</p><ul><li>Academic transcripts and certificates</li><li>English or German proof (B2+ for German courses)</li><li>Motivation letter and CV for Master''s programmes</li><li>Application fee of CHF 100</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition is low and charged per semester.</p><ul><li>Non-EU/EEA and non-Swiss students: CHF 1,250 per semester plus CHF 100 application fee</li><li>EU/EEA and Swiss students: CHF 950 per semester</li><li>Living costs: about CHF 1,800-2,500 a month (estimate; high)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> IELTS or TOEFL for English programmes; German B2+ where required</li></ul>' WHERE slug = 'liechtenstein';
UPDATE countries SET why_title = 'Why study in Andorra?', why_body = '<p>Andorra is a small Pyrenean country with the University of Andorra, which has a small international student body and specialises in nursing, IT, business and tourism.<ul><li>Small, close-knit university</li><li>Skiing and outdoor setting</li><li>Multilingual (Catalan, Spanish, French)</li><li>Close to Spain and France</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Andorra is outside the EU, so all foreign students need a specific <strong>study permit (residence and study authorisation)</strong> from the Andorran Immigration Service.</p><ul><li>Admission letter from the University of Andorra</li><li>Study permit applied for through the nearest Andorran consulate or in France or Spain</li><li>Proof of financial solvency equal to the national minimum wage (reported)</li><li>Passport and application form</li><li>Housing and permit renewal are reported obstacles for international students (2026 rector comments)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Andorran Immigration Service and the University of Andorra site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to the University of Andorra.</p><ul><li>Academic transcripts and certificates</li><li>Language proof (Catalan, Spanish, French or English)</li><li>Some programmes require Catalan</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition figures conflict in sources.</p><ul><li>WHED lists about €750 per semester for national and international students</li><li>Another guide says €1,800-€4,000 a year depending on programme</li><li>Living costs: about €900-€1,400 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> Catalan, Spanish, French or English depending on programme</li></ul>' WHERE slug = 'andorra';
COMMIT;
